from abc import ABC, abstractmethod


class User:
    def __init__(self, email):
        self.email = email


# Overengineered: interface + factory + registry for ONE implementation
class INotificationSender(ABC):
    @abstractmethod
    def send(self, user, message):
        raise NotImplementedError


class EmailNotificationSender(INotificationSender):
    def send(self, user, message):
        print(f"Emailing {user.email}: {message}")


class NotificationSenderFactory:
    _registry = {"email": EmailNotificationSender}

    @staticmethod
    def create(channel):
        sender_class = NotificationSenderFactory._registry.get(channel)
        if sender_class is None:
            raise ValueError("Unknown channel: " + channel)
        return sender_class()


class WelcomeNotifier:
    def send_welcome_message(self, user):
        sender = NotificationSenderFactory.create("email")
        sender.send(user, "Welcome aboard!")


if __name__ == "__main__":
    user = User("alice@example.com")
    notifier = WelcomeNotifier()
    notifier.send_welcome_message(user)

