// Overengineered: interface + factory + registry for ONE implementation
interface INotificationSender {
    void send(User user, String message);
}

class EmailNotificationSender implements INotificationSender {
    public void send(User user, String message) {
        System.out.println("Emailing " + user.getEmail() + ": " + message);
    }
}

class NotificationSenderFactory {
    static INotificationSender create(String channel) {
        if (channel.equals("email")) {
            return new EmailNotificationSender();
        }
        throw new IllegalArgumentException("Unknown channel: " + channel);
    }
}

class WelcomeNotifier {
    void sendWelcomeMessage(User user) {
        INotificationSender sender = NotificationSenderFactory.create("email");
        sender.send(user, "Welcome aboard!");
    }
}

class User {
    private String email;
    User(String email) { this.email = email; }
    String getEmail() { return email; }
}

public class Main {
    public static void main(String[] args) {
        User user = new User("alice@example.com");
        WelcomeNotifier notifier = new WelcomeNotifier();
        notifier.sendWelcomeMessage(user);
    }
}

