#include <iostream>
#include <string>
#include <memory>
#include <stdexcept>

class User {
public:
    explicit User(std::string email) : email_(std::move(email)) {}
    const std::string& getEmail() const { return email_; }
private:
    std::string email_;
};

// Overengineered: interface + factory + registry for ONE implementation
class INotificationSender {
public:
    virtual ~INotificationSender() = default;
    virtual void send(const User& user, const std::string& message) = 0;
};

class EmailNotificationSender : public INotificationSender {
public:
    void send(const User& user, const std::string& message) override {
        std::cout << "Emailing " << user.getEmail() << ": " << message << std::endl;
    }
};

class NotificationSenderFactory {
public:
    static std::unique_ptr<INotificationSender> create(const std::string& channel) {
        if (channel == "email") {
            return std::make_unique<EmailNotificationSender>();
        }
        throw std::invalid_argument("Unknown channel: " + channel);
    }
};

class WelcomeNotifier {
public:
    void sendWelcomeMessage(const User& user) {
        auto sender = NotificationSenderFactory::create("email");
        sender->send(user, "Welcome aboard!");
    }
};

int main() {
    User user("alice@example.com");
    WelcomeNotifier notifier;
    notifier.sendWelcomeMessage(user);
    return 0;
}

